def known(keys) -> list[str]:
    """Only keys that exist in the table, in order, without duplicates."""
    seen: list[str] = []
    for k in keys:
        if k in SOURCES and k not in seen:
            seen.append(k)
    return seen


def short(key: str) -> str:
    s = SOURCES[key]
    return f"{s['authors'].split(',')[0].split(' ')[0]} {s['year']}"


def citation_map(keys) -> dict[str, dict]:
    """Payload form for the web app: id -> {id, short, title, authors, year, journal, quality, summary, verified, doi?, url?}.

    `doi`/`url` are present only when the verification pass found one."""
    out = {}
    for k in known(keys):
        s = SOURCES[k]
        e = {"id": k, "short": short(k), "title": s["title"], "authors": s["authors"], "year": s["year"], "journal": s["venue"],
             "quality": s.get("quality", "unrated"), "summary": s.get("summary", ""), "verified": s["verified"]}
        for f in ("doi", "url"):
            if s.get(f):
                e[f] = s[f]
        out[k] = e
    return out
